        if(Get(edge,"locked",false).AsBool())return;var link=edge["link"].AsGodotDictionary();var saved=edge["saved"].AsGodotDictionary();var nodes=Map(owner,"nodes");var endpointA=edge["a"].AsGodotDictionary();var endpointB=edge["b"].AsGodotDictionary();var a=nodes[endpointA["id"]].AsGodotDictionary();var b=nodes[endpointB["id"]].AsGodotDictionary();var stateA=a["state"].AsGodotDictionary();var stateB=b["state"].AsGodotDictionary();var force=edge["linear"].AsVector3()/(float)(dt*dt);var torque=edge["angular"].AsVector3()/(float)(dt*dt);var poseA=stateA["pose"].AsTransform3D();var poseB=stateB["pose"].AsTransform3D();var frame=poseB.Basis.Orthonormalized()*Basis.FromEuler(Get(link,"orientation",Vector3.Zero).AsVector3()*(Mathf.Pi/180));double component=force.Dot(frame.Y),axial=component*((poseB.Origin-poseA.Origin).Dot(frame.Y)<0?-1:1),strength=Math.Max(.0001,Get(link,"strength",1).AsDouble()*(1-Math.Clamp(saved["damage"].AsDouble(),0,.999)));if(Get(link,"material_strength",false).AsBool())foreach(var node in new[]{a,b}){var physical=_materials.resolve(Values(controller,node["owner"].AsString(),time),Vector3.Zero);if(physical!=null){var values=physical.Get("values").AsGodotDictionary();strength*=Math.Sqrt(Math.Clamp((Get(values,"strength",10).AsDouble()+Get(values,"toughness",5).AsDouble())/20,.1,10));}}double breaking=Math.Max(.001,Get(link,"breaking_force",10000).AsDouble()*strength),bending=Math.Max(.001,Get(link,"breaking_torque",10000).AsDouble()*strength*Math.Max(.001,Get(link,"bending",1).AsDouble()));var leverA=poseA.Basis*endpointA["local"].AsVector3();var leverB=poseB.Basis*endpointB["local"].AsVector3();double moment=Math.Max(torque.Length(),Math.Max(leverA.Cross(force).Length(),leverB.Cross(force).Length())),utilization=Math.Max(Math.Max(0,axial)/(breaking*Math.Max(.001,Get(link,"tension",1).AsDouble())),Math.Max(0,-axial)/(breaking*Math.Max(.001,Get(link,"compression",1).AsDouble())));utilization=Math.Max(utilization,(force-frame.Y*(float)component).Length()/(breaking*Math.Max(.001,Get(link,"shear",1).AsDouble())));utilization=Math.Max(utilization,moment/bending);saved["load"]=force.Length();saved["torque"]=moment;saved["utilization"]=utilization;saved["force"]=force;foreach(var node in new[]{a,b}){var structural=Map(controller,"states")[node["owner"]].AsGodotDictionary()["structural"].AsGodotDictionary();structural["load"]=structural["load"].AsDouble()+force.Length();}if(!Get(link,"prevent_failure",false).AsBool()){double excess=Math.Max(0,utilization-.35);saved["damage"]=Math.Min(1,saved["damage"].AsDouble()+excess*excess*Get(link,"damage_rate",.05).AsDouble()*dt);if(utilization>=1||saved["damage"].AsDouble()>=1){saved["broken"]=true;saved["reason"]="Force / torque overload";controller.EmitSignal("connection_broken",edge["owner"],edge["key"],time);controller.Get("debris").AsGodotObject().Call("emit",controller,edge["owner"],edge["key"],"collapse",time,poseA*endpointA["local"].AsVector3(),frame.Y,stateA["v"],.5*force.LengthSquared()/Math.Max(1,link["stiffness"].AsDouble()));}}double damping=Math.Clamp(Get(link,"damping",.15).AsDouble(),0,1),total=a["inv"].AsDouble()+b["inv"].AsDouble();var relative=stateA["v"].AsVector3()-stateB["v"].AsVector3();if(total>0&&!saved["broken"].AsBool()){stateA["v"]=stateA["v"].AsVector3()-relative*(float)(damping*a["inv"].AsDouble()/total);stateB["v"]=stateB["v"].AsVector3()+relative*(float)(damping*b["inv"].AsDouble()/total);}foreach(var node in new[]{a,b}){var parent=Map(controller,"states")[node["owner"]].AsGodotDictionary();if(node["id"].AsString()!=node["owner"].AsString()||Get(parent,"destruction_detached",false).AsBool())continue;var actor=Actor(controller,node["owner"].AsString());double local=controller.Call("_local",actor,time).AsDouble();if(!Get(actor.Get("values").AsGodotDictionary(),"destruction_enabled",false).AsBool()&&_data.animation_track(actor,new[]{"destruction_enabled"})==null)continue;if(local<Get(parent,"structure_damage_next",0).AsDouble())continue;double ener