    public void update_islands(RefCounted owner,RefCounted controller)
    {
        var nodes=Map(owner,"nodes");var adjacency=new Settings();var supported=new Settings();var queue=new List<string>();var stamp=new GArray();foreach(var entry in nodes){adjacency[entry.Key]=new GArray();if(entry.Value.AsGodotDictionary()["fixed"].AsBool()){supported[entry.Key]=true;queue.Add(entry.Key.AsString());}}foreach(var value in Edges(owner)){var edge=value.AsGodotDictionary();if(edge["saved"].AsGodotDictionary()["broken"].AsBool())continue;var a=edge["a"].AsGodotDictionary()["id"];var b=edge["b"].AsGodotDictionary()["id"];adjacency[a].AsGodotArray().Add(b);adjacency[b].AsGodotArray().Add(a);stamp.Add(new GArray{a,b});}long next=(long)GD.Hash(new GArray{new GArray(nodes.Keys),stamp});var islands=Map(owner,"islands");if(owner.Get("graph_key").AsInt64()!=next){owner.Set("graph_key",next);owner.Set("graph_builds",owner.Get("graph_builds").AsInt64()+1);islands.Clear();foreach(var id in nodes.Keys){if(islands.ContainsKey(id))continue;var walk=new List<string>{id.AsString()};islands[id]=id;while(walk.Count>0){string current=walk[^1];walk.RemoveAt(walk.Count-1);foreach(var neighbor in adjacency[current].AsGodotArray())if(!islands.ContainsKey(neighbor)){islands[neighbor]=id;walk.Add(neighbor.AsString());}}}}var support=adjacency.Duplicate(true);var states=Map(controller,"states");foreach(var entry in nodes){string actorId=entry.Value.AsGodotDictionary()["owner"].AsString();foreach(var value in Get(states[actorId].AsGodotDictionary(),"structure_contacts",new GArray()).AsGodotArray()){var hit=value.AsGodotDictionary();if(hit["normal"].AsVector3().Dot(Vector3.Up)<.35)continue;string target=hit["actor"].AsString();if(nodes.ContainsKey(target))support[target].AsGodotArray().Add(entry.Key);else if(states.ContainsKey(target)&&states[target].AsGodotDictionary()["active"].AsBool()&&!Get(states[target].AsGodotDictionary(),"responds",false).AsBool()){supported[entry.Key]=true;queue.Add(entry.Key.AsString());}}}while(queue.Count>0){string id=queue[^1];queue.RemoveAt(queue.Count-1);foreach(var neighbor in support[id].AsGodotArray())if(!supported.ContainsKey(neighbor)){supported[neighbor]=true;queue.Add(neighbor.AsString());}}foreach(var entry in nodes){var structural=states[entry.Value.AsGodotDictionary()["owner"]].AsGodotDictionary()["structural"].AsGodotDictionary();var island=islands.TryGetValue(entry.Key,out var root)?root:entry.Key;structural["supported"]=structural["supported"].AsBool()||supported.ContainsKey(entry.Key);structural["island"]=island;structural["fragments"].AsGodotDictionary()[entry.Key]=new Settings{["supported"]=supported.ContainsKey(entry.Key),["island"]=island};}
